INSERT INTO `courses` (`course_id`, `org_id`, `primary_instructor_id`, `title`, `description`, `proficiency`, `learning_hours`, `fee`, `created_at`, `last_updated`) VALUES
(1, 11, 470, 'Advanced Professional Communication Skills Development', 'Learners will master strategic communication techniques essential for leadership roles, including stakeholder engagement, difficult conversations, and cross-functional collaboration. This course equips professionals with practical tools to enhance clarity, persuasion, and emotional intelligence in complex corporate environments.', 'Intermediate', 13, 0, '2023-03-20 23:29:40', '2024-01-16 15:38:02'),
(2, 3, 438, 'Advanced Data Analysis and Predictive Modeling', 'Master advanced statistical techniques and machine learning algorithms to extract actionable insights from complex datasets. This comprehensive course equips professionals with the skills to build predictive models, perform sophisticated data transformations, and implement data-driven decision-making strategies in enterprise environments.', 'Advanced', 26, 229, '2023-03-22 17:12:47', '2024-03-28 17:49:24'),
(3, 10, 470, 'Advanced Product Management: Strategy, Analytics, and Execution', 'Learners will master advanced product management frameworks, data-driven decision-making, and cross-functional leadership techniques to drive product success in competitive markets. This course equips professionals with practical strategies for prioritization, roadmap development, user research, and stakeholder management while building expertise in analytics and metrics-driven product optimization.', 'Intermediate', 23, 260, '2023-04-11 16:15:49', '2023-04-23 22:12:47'),
(4, 7, 162, 'Mastering Advanced UX Design Principles and Methods', 'This intermediate-level course enables professionals to deepen their UX design expertise by mastering advanced principles, research methodologies, and modern design frameworks. Learners will develop skills in conducting comprehensive user research, creating sophisticated wireframes and prototypes, and implementing accessibility standards while learning industry best practices used by leading tech companies.', 'Intermediate', 10, 215, '2023-04-29 12:16:55', '2024-06-04 07:25:35'),
(5, 5, 314, 'Advanced Agile Transformation and Enterprise Scaling', 'Master enterprise-wide agile transformation strategies and learn to scale agile frameworks across complex organizational structures. This advanced course covers SAFe, LeSS, and Spotify models while addressing real-world challenges of implementing agile in large corporations, managing stakeholder alignment, and optimizing delivery pipelines for maximum competitive advantage.', 'Advanced', 27, 387, '2023-04-30 19:17:01', '2023-09-07 05:47:37'),
(6, 10, 45, 'Advanced Product Strategy and Market Leadership', 'Develop strategic expertise in product roadmapping, competitive positioning, and stakeholder management to drive organizational growth and market differentiation. This advanced course equips experienced product managers with frameworks for navigating complex market dynamics, building scalable products, and leading high-performing cross-functional teams in competitive landscapes.', 'Advanced', 44, 277, '2023-05-21 04:05:11', '2024-05-20 21:45:41'),
(7, 6, 448, 'UX Design Fundamentals for Modern Digital Products', 'Learn the core principles of user experience design and apply them to create intuitive, user-centered digital products. This beginner-friendly course covers research methods, wireframing, prototyping, and usability testing to establish a strong foundation in UX design practice.', 'Beginner', 5, 121, '2023-05-23 06:43:49', '2024-01-09 03:26:46'),
(8, 2, 395, 'Executive Communication Strategy and Influence', 'Learners will master advanced communication frameworks, executive presence, and strategic influence techniques essential for senior leadership roles. This course develops capabilities in stakeholder management, high-stakes presentations, and organizational communication that drives business outcomes.', 'Advanced', 37, 312, '2023-07-02 14:19:15', '2024-12-26 10:55:47'),
(9, 10, 419, 'Advanced UX Design: Enterprise Systems and Digital Strategy', 'Learners will master complex UX design methodologies for enterprise-level applications, including advanced research techniques, scalable design systems, and strategic thinking for large-scale digital transformations. This course equips professionals to lead cross-functional teams, implement data-driven design decisions, and architect user experiences that drive measurable business impact in mission-critical environments.', 'Advanced', 31, 454, '2023-06-23 14:47:16', '2023-07-04 05:59:31'),
(10, 7, 466, 'Scaling Agile: Enterprise Transformation and Leadership', 'Discover advanced strategies for implementing Agile at enterprise scale, including SAFe frameworks, organizational change management, and cross-functional team dynamics. This course equips senior leaders and Agile coaches with proven methodologies to drive sustainable digital transformation, optimize delivery pipelines, and build high-performing distributed teams in complex corporate environments.', 'Advanced', 39, 494, '2023-07-11 02:34:14', '2024-04-13 02:54:45'),
(11, 9, 137, 'Advanced Agile Transformation: Scaling Enterprise Methodologies', 'Develop mastery in implementing Agile frameworks across large-scale organizations and complex enterprise environments. Learners will gain advanced skills in SAFe, scaling strategies, organizational change management, and leading high-performing distributed Agile teams at the executive and leadership level.', 'Advanced', 37, 362, '2023-08-08 08:19:06', '2023-12-30 13:40:34'),
(12, 5, 382, 'Advanced Project Management: Strategic Leadership and Execution', 'Master complex project portfolios and enterprise-level delivery strategies through proven frameworks and real-world case studies. Learners will develop advanced competencies in stakeholder management, risk mitigation, and organizational alignment to lead mission-critical initiatives in dynamic business environments.', 'Advanced', 21, 460, '2023-08-03 18:04:12', '2024-08-09 11:33:57'),
(13, 6, 138, 'Advanced UX Design: Systems, Strategy, and Enterprise Solutions', 'Master advanced UX design methodologies including design systems, strategic research frameworks, and enterprise-scale implementations. This course equips design professionals with the expertise to lead complex digital transformation initiatives and create scalable design solutions across large organizations.', 'Advanced', 43, 372, '2023-08-20 21:29:42', '2023-12-25 19:07:35'),
(14, 12, 181, 'Advanced Software Architecture and System Design Mastery', 'This advanced course equips experienced engineers with architectural principles, design patterns, and systems thinking required to lead complex software projects. Learners will master microservices architecture, scalability strategies, and enterprise-level design decisions while developing competency in evaluating trade-offs and mentoring junior developers.', 'Advanced', 26, 0, '2023-09-08 14:47:21', '2024-07-17 16:56:08'),
(15, 7, 45, 'Advanced Agile Methodologies and Team Leadership', 'This intermediate course equips professionals with advanced Agile frameworks, sprint optimization techniques, and cross-functional team management skills. Learners will master stakeholder communication, backlog prioritization, velocity tracking, and gain practical strategies for scaling Agile across enterprise environments.', 'Intermediate', 19, 140, '2023-10-04 08:35:31', '2024-11-30 21:25:34'),
(16, 2, 112, 'Effective Communication Fundamentals for Workplace Success', 'Learners will master essential communication skills including active listening, clear message delivery, and professional written communication. This course provides practical frameworks and real-world scenarios to help employees communicate more effectively with colleagues, managers, and clients across various workplace situations.', 'Beginner', 8, 121, '2023-10-19 19:41:34', '2024-07-12 16:06:52'),
(17, 6, 137, 'Advanced Project Management: Strategic Leadership and Execution', 'This advanced course equips experienced project managers with sophisticated methodologies for managing complex, high-stakes initiatives across distributed teams and global organizations. Learners will master advanced risk management, stakeholder engagement strategies, and decision-making frameworks while developing the leadership competencies required to drive organizational success in competitive markets.', 'Advanced', 37, 347, '2023-11-06 18:37:57', '2023-12-15 06:27:47'),
(18, 4, 317, 'Advanced Software Engineering Architecture and Systems Design', 'Master enterprise-level software design patterns, microservices architecture, and scalable system design principles. This course equips seasoned developers with the skills to architect complex distributed systems, implement domain-driven design, and lead technical decisions in mission-critical environments.', 'Advanced', 39, 420, '2023-11-02 15:56:04', '2024-04-20 13:52:55'),
(19, 3, 55, 'Advanced Project Management: Strategic Delivery and Leadership', 'This advanced course equips experienced project managers with strategic frameworks and leadership techniques to oversee complex, multi-stakeholder initiatives in dynamic corporate environments. Learners will master enterprise-level portfolio management, risk mitigation, organizational change management, and develop the executive presence required to influence decision-making at the C-suite level.', 'Advanced', 39, 316, '2023-11-25 21:42:37', '2024-12-27 20:52:23'),
(20, 1, 271, 'Executive Communication Mastery: Influence and Impact', 'This advanced course equips leaders with sophisticated communication strategies to influence organizational decisions, manage complex stakeholder relationships, and deliver compelling narratives across diverse audiences. Learners will master executive presence, crisis communication, and persuasive speaking techniques essential for senior leadership roles.', 'Advanced', 40, 327, '2023-11-27 15:49:08', '2024-06-11 03:57:28'),
(21, 4, 6, 'Scaling Software Systems: Design Patterns and Architecture', 'Learn advanced architectural principles, enterprise design patterns, and best practices for building scalable software systems in production environments. This course covers microservices architecture, system design trade-offs, distributed systems concepts, and real-world implementation strategies used by leading tech companies to deliver reliable and maintainable applications.', 'Intermediate', 17, 169, '2023-12-19 14:16:31', '2024-06-12 07:02:48'),
(22, 6, 63, 'Advanced Software Engineering: Design Patterns and System Architecture', 'Learners will master advanced architectural principles, design patterns, and enterprise-level system design techniques to lead complex software projects. This course covers SOLID principles, microservices architecture, scalable system design, and real-world implementation strategies used in Fortune 500 companies.', 'Advanced', 29, 369, '2023-12-30 20:47:37', '2024-04-24 03:29:37'),
(23, 3, 470, 'Agile Fundamentals for Modern Teams', 'This beginner-level course introduces learners to core Agile principles, methodologies, and practices essential for today''s dynamic work environments. Participants will gain foundational knowledge of Agile frameworks like Scrum and Kanban, understand iterative development cycles, and learn how to collaborate effectively in cross-functional teams. By the end of this course, learners will be equipped to contribute meaningfully to Agile projects and support organizational transformation initiatives.', 'Beginner', 7, 99, '2024-01-01 02:43:23', '2024-02-28 05:18:15'),
(24, 12, 271, 'Advanced Software Architecture and Design Patterns', 'Master enterprise-level software design principles, architectural patterns, and best practices for building scalable, maintainable systems. This course covers domain-driven design, microservices architecture, system scalability, and code quality optimization techniques used in Fortune 500 companies.', 'Advanced', 28, 250, '2024-01-18 19:11:05', '2025-01-04 09:51:16'),
(25, 1, 191, 'Advanced UX Design: Enterprise Systems and Design Systems', 'Master enterprise-level UX design principles and methodologies for complex systems. This advanced course equips design professionals with frameworks for conducting sophisticated user research, building scalable design systems, and leading cross-functional teams to deliver exceptional user experiences in large-scale corporate environments. Learners will gain practical expertise in advanced prototyping, accessibility compliance, and data-driven design decisions for mission-critical applications.', 'Advanced', 39, 252, '2024-02-19 10:08:56', '2024-09-07 20:27:11'),
(26, 12, 63, 'Advanced Project Management: Strategic Planning and Execution', 'Master sophisticated project management methodologies including advanced risk analysis, stakeholder management, and portfolio optimization. Learners will develop expertise in leading complex, multi-phase initiatives while aligning projects with organizational strategy and managing cross-functional teams effectively.', 'Advanced', 26, 298, '2024-03-09 11:54:13', '2024-09-07 15:43:52'),
(27, 3, 500, 'Advanced Project Management: Enterprise Strategy and Execution', 'Master sophisticated project management methodologies including portfolio optimization, stakeholder engagement at executive levels, and risk mitigation across complex, multi-phase initiatives. This course equips senior professionals with advanced frameworks for leading transformational projects in dynamic corporate environments and delivering measurable business value.', 'Advanced', 22, 0, '2024-03-01 14:09:37', '2024-10-18 10:02:15'),
(28, 10, 340, 'Strategic Leadership and Organizational Transformation', 'Develop advanced leadership capabilities to drive organizational change and lead high-performing teams through complex business challenges. This course equips senior leaders with frameworks for strategic decision-making, change management, and building resilient organizational cultures in today''s dynamic business environment.', 'Advanced', 20, 479, '2024-04-03 16:59:48', '2024-07-05 12:01:22'),
(29, 10, 382, 'Advanced Product Management: Strategy to Market Launch', 'Learn to develop comprehensive product strategies, manage cross-functional teams, and successfully launch products in competitive markets. This course equips intermediate product managers with advanced frameworks, real-world case studies, and practical tools to drive product success and business growth.', 'Intermediate', 10, 0, '2024-03-23 21:15:24', '2025-01-16 18:56:20'),
(30, 10, 137, 'Advanced Project Management Strategy and Execution', 'Master complex project management methodologies, risk mitigation strategies, and stakeholder management techniques essential for leading large-scale enterprise initiatives. Learners will develop expertise in advanced planning, resource optimization, and delivery frameworks to drive organizational success in competitive business environments.', 'Advanced', 29, 227, '2024-04-13 15:22:45', '2024-11-23 13:31:19'),
(31, 5, 191, 'Advanced Data Analysis and Business Intelligence', 'Master intermediate data analysis techniques to transform raw data into actionable business insights. Learners will develop proficiency in advanced statistical analysis, data visualization, and reporting tools while applying real-world scenarios from corporate environments. Upon completion, participants will be equipped to lead data-driven decision-making initiatives and optimize business performance through sophisticated analytical methodologies.', 'Intermediate', 21, 113, '2024-05-12 18:20:45', '2025-01-15 14:04:34'),
(32, 4, 448, 'Foundations of Effective Leadership for Emerging Leaders', 'This beginner-level course introduces essential leadership principles and practical strategies for newly promoted managers and aspiring leaders. Learners will master core competencies including emotional intelligence, communication, decision-making, and team motivation to build a strong foundation for their leadership journey. By completing this course, participants will gain the confidence and tools needed to inspire teams, manage conflicts constructively, and drive organizational success.', 'Beginner', 7, 0, '2024-05-24 02:50:10', '2024-09-19 17:47:51'),
(33, 1, 138, 'Strategic Leadership: Driving Organizational Change and Performance', 'Develop advanced leadership capabilities to drive strategic initiatives, manage complex organizational transformations, and inspire high-performing teams. This course equips senior leaders with frameworks for visionary thinking, stakeholder management, and sustainable business impact in competitive markets.', 'Advanced', 44, 211, '2024-05-29 20:39:43', '2024-10-19 19:29:19'),
(34, 5, 162, 'Data Analysis Fundamentals for Business Professionals', 'This comprehensive beginner course equips professionals with essential data analysis skills, including data collection, cleaning, visualization, and interpretation techniques. Learners will gain practical knowledge in using industry-standard tools and methodologies to extract actionable insights from business data, enabling data-driven decision-making in their organizations.', 'Beginner', 6, 0, '2024-06-10 18:18:58', '2024-09-19 06:10:58'),
(35, 2, 6, 'Advanced Project Management: Strategic Execution and Leadership', 'Master sophisticated project management methodologies including advanced risk mitigation, stakeholder engagement, and portfolio optimization. This course equips experienced professionals with frameworks for managing complex multi-million dollar initiatives while developing leadership competencies in resource allocation, budget forecasting, and organizational change management.', 'Advanced', 21, 415, '2024-06-13 09:26:32', '2024-07-25 22:06:24'),
(36, 5, 436, 'Strategic Leadership and Organizational Transformation', 'This advanced course equips senior leaders with frameworks and strategies for driving organizational change, building high-performing teams, and navigating complex business challenges. Learners will develop critical competencies in executive decision-making, stakeholder management, and sustainable leadership practices to create lasting impact across their organizations.', 'Advanced', 43, 220, '2024-06-28 05:53:13', '2024-11-13 07:31:25'),
(37, 11, 162, 'Scaling Agile: Advanced Team Leadership and Frameworks', 'This intermediate course equips experienced practitioners with advanced Agile methodologies including SAFe, LeSS, and Nexus frameworks for managing complex multi-team environments. Learners will master stakeholder communication, dependency management, and organizational change strategies to effectively scale Agile practices across enterprise teams.', 'Intermediate', 11, 108, '2024-07-10 16:43:36', '2025-01-11 12:15:13'),
(38, 4, 441, 'Advanced Software Engineering: System Design and Architecture', 'This advanced course equips software engineers with the knowledge to design scalable, maintainable systems and make critical architectural decisions. Learners will master distributed systems principles, microservices patterns, design patterns, and enterprise architecture practices used in production environments across leading tech companies.', 'Advanced', 37, 246, '2024-07-24 10:39:23', '2024-08-04 09:52:13'),
(39, 11, 448, 'Advanced Professional Communication in Corporate Settings', 'This intermediate-level course equips professionals with advanced communication strategies to navigate complex workplace interactions, including cross-functional collaboration, stakeholder management, and persuasive presentation techniques. Learners will master active listening, emotional intelligence in communication, and conflict resolution skills to become more influential leaders and team members. By completing this course, participants will enhance their ability to articulate ideas clearly, build stronger professional relationships, and drive organizational success through improved communication effectiveness.', 'Intermediate', 16, 204, '2024-09-04 17:24:46', '2024-11-11 11:48:41'),
(40, 11, 277, 'Enterprise Agile Transformation: Leading Scaled Agile Frameworks', 'This advanced course equips organizational leaders and agile coaches with strategies to implement and scale agile methodologies across enterprise environments. Learners will master SAFe principles, organizational change management, and advanced coaching techniques to drive sustainable agile transformation in complex, multi-team organizations.', 'Advanced', 43, 353, '2024-09-07 19:38:37', '2024-12-16 19:10:54'),
(41, 1, 470, 'Advanced Data Analysis and Statistical Modeling Techniques', 'This advanced course equips professionals with sophisticated data analysis methodologies, statistical modeling, and predictive analytics skills essential for driving strategic business decisions. Learners will master advanced visualization techniques, multivariate analysis, hypothesis testing, and machine learning integration to extract actionable insights from complex datasets.', 'Advanced', 44, 0, '2024-09-11 13:35:19', '2025-01-10 08:38:42'),
(42, 3, 441, 'Advanced User Experience Design for Enterprise Products', 'This advanced course equips experienced designers with cutting-edge methodologies for designing complex enterprise systems and SaaS platforms at scale. Learners will master advanced usability research techniques, design system governance, accessibility compliance, and the strategic integration of UX design with business objectives and product roadmaps.', 'Advanced', 29, 236, '2024-10-07 18:21:17', '2024-12-13 12:45:23'),
(43, 10, 277, 'Advanced Product Strategy: Market Leadership and Execution', 'This advanced course equips experienced product managers with strategic frameworks for defining competitive positioning, driving market expansion, and scaling product portfolios across complex organizational structures. Learners will master cross-functional stakeholder management, data-driven decision making, and advanced roadmapping techniques to lead high-impact product initiatives in competitive markets.', 'Advanced', 29, 453, '2024-10-17 12:21:18', '2024-11-18 03:16:43'),
(44, 7, 448, 'Advanced Data Analysis and Predictive Modeling', 'Master advanced statistical techniques, machine learning algorithms, and predictive modeling to drive strategic business decisions. Learners will develop expertise in complex data analysis, hypothesis testing, and building predictive models using industry-standard tools and methodologies.', 'Advanced', 38, 358, '2024-10-18 12:59:03', '2024-12-20 20:42:09'),
(45, 9, 479, 'Advanced Project Portfolio Management and Strategic Governance', 'This advanced course equips seasoned project managers with sophisticated portfolio management techniques, stakeholder governance frameworks, and enterprise-level risk orchestration strategies. Learners will master multi-project alignment, resource optimization across portfolios, and develop executive-level decision-making skills for complex organizational initiatives.', 'Advanced', 23, 261, '2024-11-08 10:31:56', '2024-11-25 17:10:46'),
(46, 9, 470, 'Advanced Project Management: Execution and Control Strategies', 'Develop mastery in managing complex projects through proven execution frameworks and real-world control methodologies. This intermediate course equips professionals with the essential skills to deliver projects on time and within budget while managing stakeholder expectations and team dynamics effectively.', 'Intermediate', 23, 245, '2024-12-08 16:50:01', '2024-12-21 17:51:54'),
(47, 5, 63, 'Agile Frameworks and Sprint Mastery in Practice', 'Master advanced Agile methodologies, Sprint planning, and team coordination to deliver complex projects effectively. This intermediate course equips professionals with practical skills in managing stakeholder expectations, optimizing team velocity, and implementing continuous improvement cycles.', 'Intermediate', 24, 0, '2024-11-27 17:41:18', '2025-01-19 07:49:09'),
(48, 5, 470, 'Advanced Professional Communication for Corporate Excellence', 'Master essential communication strategies to enhance leadership presence, influence stakeholder decisions, and build stronger working relationships. Learners will develop practical skills in executive-level presentations, cross-functional collaboration, and strategic messaging techniques applicable to modern workplace scenarios.', 'Intermediate', 19, 282, '2024-12-12 01:12:22', '2024-12-19 13:19:12'),
(49, 4, 470, 'Advanced UX Design: Strategy and Implementation', 'Learners will master advanced UX design principles, user research methodologies, and prototyping techniques to create compelling digital experiences. This course equips professionals with the skills to conduct user interviews, perform competitive analysis, and implement design systems in real-world corporate environments.', 'Intermediate', 16, 119, '2025-01-13 19:05:13', '2025-01-19 04:01:48'),
(50, 11, 271, 'Advanced UX Design Principles and Digital Strategy', 'Master modern UX design methodologies including user research, interaction design, and usability testing to create engaging digital experiences. This intermediate course equips designers with proven frameworks and practical tools to solve complex design problems and lead design initiatives within enterprise environments. Learners will develop expertise in accessibility standards, design systems, and cross-functional collaboration to deliver measurable business impact.', 'Intermediate', 15, 198, '2025-01-24 20:27:32', '2025-01-21 18:23:48');


