INSERT INTO `instructors` (`instructor_id`, `introduction`, `started_date`, `last_online`, `degree_of_study`, `institution`, `certification`) VALUES
(4, 'Diane Ruiz is an accomplished instructor specializing in Data Analysis and Project Management, bringing a wealth of practical knowledge from her background as a UX Designer. With expertise in translating complex data into actionable insights and managing cross-functional teams, she combines technical proficiency with user-centered thinking to deliver engaging and impactful instruction. Diane is dedicated to empowering students with the skills necessary to drive data-informed decision-making and lead successful projects in today''s dynamic business environment.', '2023-02-12', '2025-12-01 07:11:46', 'Ph.D. in Computer Science', 'UC Berkeley', 'PHR'),
(6, 'Jack Romero is an instructor specializing in Data Analysis and Communication, bringing a unique perspective informed by his extensive background in UX design. With a deep understanding of how to translate complex data insights into compelling narratives, Jack equips students with both the analytical and communication skills essential for success in today''s data-driven world. His practical experience in user-centered design enables him to create engaging learning experiences that bridge the gap between technical analysis and effective stakeholder communication.', '2023-02-16', '2024-12-21 10:11:32', 'M.S. in Information Systems', 'Northwestern University', 'CSM'),
(45, 'Blake Miller is an accomplished Software Engineering and Data Analysis instructor with a strong educational background in teaching. With a passion for demystifying complex technical concepts, Blake brings expertise and clarity to every classroom, helping students master both programming fundamentals and advanced data analysis techniques. Dedicated to fostering an engaging learning environment, Blake combines real-world industry insights with pedagogical excellence to prepare students for successful careers in technology.', '2023-04-30', '2025-11-09 15:07:07', 'M.S. in Human-Computer Interaction', 'Georgia Tech', 'Six Sigma Black Belt'),
(55, 'Molly Gonzales is an experienced UX Design and Agile instructor with a strong background in Software Engineering. With her unique blend of technical expertise and user-centered design philosophy, she brings practical, real-world insights to her courses that empower students to create innovative digital solutions. Molly is dedicated to helping learners master both the strategic principles of user experience and the collaborative practices of Agile methodologies to drive meaningful impact in their careers.', '2023-04-05', '2025-08-14 08:01:43', 'Ph.D. in Computer Science', 'Stanford University', 'Six Sigma Black Belt'),
(63, 'Niamh Lawson is an experienced instructor specializing in Project Management and UX Design, bringing a unique perspective shaped by her career transition journey. With a background as a career changer, she combines practical industry knowledge with a deep understanding of navigating professional transitions, enabling her to connect with diverse learners. Niamh is dedicated to equipping students with the skills and confidence needed to excel in dynamic project environments while creating user-centered solutions that drive meaningful impact.', '2023-05-08', '2024-07-12 11:36:32', 'MBA', 'Columbia University', 'PHR'),
(112, 'Micah Coleman is an accomplished instructor specializing in Project Management and Product Management, bringing practical expertise from a robust background as an Operations Manager. With extensive experience in streamlining processes, optimizing resources, and delivering results in fast-paced environments, Micah equips students with actionable frameworks and industry best practices to excel in their careers. Passionate about fostering the next generation of project and product leaders, Micah combines strategic insights with hands-on mentorship to inspire professional growth and success.', '2023-07-27', '2024-11-16 17:51:26', 'M.A. in Education', 'University of Chicago', 'Lean Six Sigma Green Belt'),
(137, 'Luc Graves is an experienced instructor specializing in Project Management and Data Analysis, bringing a robust educational background to the classroom. With a foundation in teaching, Luc has developed a dynamic and engaging instructional approach that demystifies complex concepts and empowers students to excel in their professional careers. Dedicated to fostering practical skill development and analytical thinking, Luc creates a learning environment where students gain both theoretical knowledge and real-world competencies.', '2023-08-25', '2025-02-10 18:04:38', 'MBA in Technology Management', 'Duke University', 'PMP'),
(138, 'Danielle Harris is an experienced instructor specializing in Communication and Project Management courses, bringing a unique perspective shaped by her background in Software Engineering. With deep technical expertise and a passion for developing future leaders, Danielle combines practical industry knowledge with engaging teaching methodologies to help students master both interpersonal and organizational skills. Her dual focus on clear communication and effective project execution equips learners with the essential competencies needed to succeed in today''s dynamic professional environments.', '2023-09-09', '2024-02-15 17:34:26', 'Ph.D. in Computer Science', 'MIT', 'Google Cloud Professional'),
(162, 'Arthur Murphy is an accomplished instructor specializing in Leadership and Software Engineering, bringing a unique perspective shaped by his extensive background as a Healthcare Administrator. With deep expertise in both technical systems and organizational management, Arthur excels at equipping students with the practical skills and strategic thinking necessary to lead in today''s technology-driven environment. His diverse professional experience enables him to bridge the gap between software development and business acumen, fostering well-rounded leaders prepared to tackle complex challenges.', '2023-10-03', '2024-09-16 14:31:04', 'M.S. in Engineering Management', 'University of Michigan', 'CFA'),
(178, 'Oscar Gilbert is an experienced instructor specializing in Product Management and Project Management courses, bringing a unique perspective shaped by his background in accounting. With a deep understanding of financial principles and operational efficiency, Oscar delivers practical, results-oriented instruction that emphasizes both strategic vision and fiscal responsibility. His courses equip students with the analytical rigor and business acumen necessary to excel in today''s dynamic product and project environments.', '2023-10-22', '2025-08-25 00:14:38', 'M.S. in Human-Computer Interaction', 'Stanford University', 'Certified Scrum Product Owner'),
(181, 'Victor Wong is an experienced instructor specializing in Leadership and Agile methodologies, bringing practical insights from his background as a Project Coordinator. With a deep understanding of dynamic team environments and project execution, Victor empowers professionals to develop their leadership capabilities and master agile frameworks that drive organizational success. His engaging teaching approach combines real-world experience with contemporary best practices, making complex concepts accessible and actionable for learners at all levels.', '2023-10-31', '2025-09-14 23:59:25', 'M.S. in Data Science', 'Duke University', 'SAFe Agilist'),
(190, 'Daniel Patel is an accomplished instructor specializing in Product Management and UX Design, bringing over a decade of experience from a robust background in Software Engineering. With a deep understanding of both technical implementation and user-centered design principles, he equips students with practical knowledge and industry insights to excel in today''s competitive product landscape. Daniel is committed to fostering innovation and critical thinking among his students, helping them bridge the gap between engineering excellence and exceptional user experiences.', '2023-11-11', '2024-02-16 13:18:39', 'MBA', 'Northwestern University', 'CFA'),
(191, 'Angus Walsh is an accomplished instructor specializing in Product Management and Software Engineering, bringing a wealth of practical expertise from his background as an Operations Manager. With a proven track record of optimizing processes and leading cross-functional teams, Angus translates real-world operational insights into engaging curriculum that prepares students for success in today''s dynamic tech industry. His unique perspective bridging operations and product development equips learners with the strategic mindset and technical acumen essential for driving innovation and delivering value.', '2023-10-27', '2025-11-22 23:21:49', 'M.A. in Organizational Psychology', 'Stanford University', 'AWS Solutions Architect'),
(271, 'Autumn Ryan is an experienced instructor specializing in Leadership and Communication courses, bringing a wealth of practical knowledge from a background as a consultant. With a proven track record of developing high-impact training programs, Autumn equips students with essential skills for navigating complex organizational dynamics and fostering meaningful workplace relationships. Her engaging teaching style and real-world insights create a dynamic learning environment where professionals can build confidence in their leadership capabilities and communication effectiveness.', '2024-02-25', '2025-03-13 14:29:15', 'M.S. in Engineering Management', 'Northwestern University', 'SAFe Agilist'),
(277, 'Walter Hernandez is an accomplished instructor specializing in Leadership and Communication courses, bringing years of practical experience and pedagogical expertise to the classroom. With a strong background in education, he is dedicated to developing students'' critical thinking and interpersonal skills through dynamic, real-world applications. His engaging teaching style and commitment to student success make him an invaluable resource for professionals seeking to enhance their leadership capabilities.', '2024-03-01', '2025-05-02 03:17:20', 'M.S. in Engineering Management', 'Stanford University', 'SHRM-SCP'),
(314, 'Arpita Thakkar is an accomplished instructor specializing in Communication and Project Management courses, bringing valuable expertise from her extensive background as a consultant. With a proven track record of translating complex business concepts into practical, actionable insights, she guides students in developing critical skills essential for professional success and organizational excellence. Her teaching philosophy emphasizes real-world application and collaborative learning, enabling students to build confidence and competence in managing projects and communicating effectively across diverse teams and stakeholders.', '2024-04-28', '2025-09-18 17:44:33', 'Ph.D. in Business Administration', 'Duke University', 'SHRM-SCP'),
(317, 'Manoj Trivedi is an accomplished instructor specializing in Leadership and Communication courses, bringing a wealth of practical expertise from his extensive background as a Marketing Manager. With a proven track record of developing strategic initiatives and leading high-performing teams, he is passionate about equipping professionals with the essential skills needed to inspire, communicate effectively, and drive organizational success. His dynamic teaching approach combines real-world industry insights with contemporary leadership principles, creating an engaging learning environment that prepares students to excel as influential leaders in their respective fields.', '2024-06-02', '2024-10-21 07:03:11', 'M.S. in Human-Computer Interaction', 'Duke University', 'SHRM-SCP'),
(340, 'Oliver Wallace is an experienced instructor specializing in Communication and Software Engineering courses, bringing a unique perspective that bridges technical expertise with effective communication strategies. With a professional background as a Marketing Manager, Oliver leverages his deep understanding of audience engagement and strategic messaging to help students develop both technical competencies and interpersonal skills essential for success in the technology industry. His innovative teaching approach combines practical industry insights with collaborative learning experiences, empowering students to excel in their academic and professional endeavors.', '2024-06-22', '2025-02-14 17:16:57', 'M.A. in Education', 'Harvard Business School', 'Six Sigma Black Belt'),
(382, 'Callum Thomas is an experienced instructor specializing in Project Management and Leadership development, bringing a unique analytical perspective to organizational excellence. With a strong background in data analysis, Callum leverages data-driven insights to help students master complex project methodologies and develop the strategic leadership skills essential for modern business environments. His innovative teaching approach combines practical frameworks with real-world applications, empowering professionals to lead high-performing teams and deliver impactful results.', '2024-08-11', '2025-12-08 04:12:40', 'M.S. in Information Systems', 'Duke University', 'Lean Six Sigma Green Belt'),
(395, 'Denise Griffin is an experienced instructor specializing in Communication and Product Management, bringing a wealth of practical knowledge from her background as an Operations Manager. With a deep understanding of how effective communication drives product success and organizational efficiency, she designs engaging courses that equip students with real-world skills applicable to today''s dynamic business environment. Denise is dedicated to fostering collaborative learning experiences that empower her students to become strategic communicators and innovative product leaders.', '2024-09-07', '2025-02-13 21:52:40', 'MBA', 'Columbia University', 'ITIL Foundation'),
(419, 'Zoe Estrada is an experienced instructor specializing in Agile methodologies and UX Design, bringing a unique perspective shaped by her background as an Operations Manager. With a strong foundation in process optimization and team coordination, Zoe effectively bridges the gap between operational efficiency and user-centered design principles in her courses. Her engaging teaching style and practical industry experience make her an invaluable mentor for professionals seeking to develop expertise in modern development practices and user experience excellence.', '2024-10-16', '2025-07-16 01:06:39', 'Ph.D. in Computer Science', 'MIT', 'Certified Scrum Product Owner'),
(433, 'Greyson Bell is an accomplished instructor specializing in Software Engineering and Communication courses, bringing a unique interdisciplinary perspective shaped by a background in nursing. With experience bridging technical expertise and interpersonal skills, Greyson is passionate about equipping students with both robust software development capabilities and the communication proficiency essential for successful collaboration in today''s technology-driven workplace. Known for creating engaging, practical learning experiences, Greyson is committed to fostering the next generation of thoughtful, communicative technical professionals.', '2024-11-07', '2025-01-24 14:59:56', 'Ph.D. in Business Administration', 'University of Pennsylvania', 'ITIL Foundation'),
(436, 'Betty Munoz is an experienced Agile and Leadership instructor who brings a wealth of pedagogical expertise to the classroom, having built a strong foundation in teaching methodologies throughout her career. With her background as an educator, Betty brings authentic, engaging instruction that transforms complex Agile principles and leadership concepts into accessible, practical knowledge for her students. She is passionate about fostering collaborative learning environments and empowering professionals to lead teams with agility, resilience, and vision.', '2024-11-01', '2025-10-27 22:16:23', 'M.A. in Education', 'Carnegie Mellon University', 'Certified Scrum Product Owner'),
(438, 'Lillian Robinson is an experienced instructor specializing in Data Analysis and Leadership courses, bringing a wealth of practical expertise from her background as a Financial Analyst. With a keen ability to translate complex data insights into actionable business strategies, Lillian empowers students to develop critical analytical and leadership skills essential for modern business environments. Her dynamic teaching approach combines real-world financial analysis experience with contemporary leadership principles, preparing professionals to excel in data-driven decision-making roles.', '2024-11-14', '2026-01-10 13:37:43', 'Ph.D. in Business Administration', 'Georgia Tech', 'CSM'),
(441, 'Kathryn Stevens is an accomplished instructor specializing in Leadership and Communication courses, bringing a unique perspective shaped by her extensive background in UX Design. Her experience in creating user-centered solutions translates seamlessly into her teaching philosophy, where she emphasizes clear communication, empathetic leadership, and the importance of understanding stakeholder needs. Kathryn is dedicated to equipping her students with practical skills and insights that drive both personal growth and organizational success.', '2024-12-07', '2025-04-29 16:49:52', 'MBA in Technology Management', 'University of Pennsylvania', 'SHRM-SCP'),
(448, 'Courtney Gonzalez is an experienced instructor specializing in Project Management and Communication, bringing a wealth of practical knowledge gained from her background as a Sales Manager. With a deep understanding of team dynamics, stakeholder engagement, and strategic planning, she equips students with the skills necessary to lead projects effectively and communicate with clarity and confidence. Her dynamic teaching approach combines real-world insights with actionable frameworks, empowering learners to excel in today''s collaborative professional environment.', '2024-12-08', '2024-12-30 17:23:14', 'M.S. in Engineering Management', 'MIT', 'AWS Solutions Architect'),
(466, 'Paige Murray is an accomplished instructor specializing in UX Design and Leadership development, bringing a wealth of practical experience from her background as an HR Manager. With a unique perspective that bridges human resources strategy and user-centered design, Paige equips her students with the skills to create meaningful digital experiences while fostering strong leadership capabilities. Her courses combine industry best practices with real-world insights, helping professionals excel in both technical design and people-focused leadership roles.', '2024-12-25', '2025-01-18 15:48:04', 'M.S. in Human-Computer Interaction', 'Columbia University', 'Google Cloud Professional'),
(470, 'Owen Romero is an experienced UX Design and Leadership instructor who brings a unique perspective from their background in teaching. With a passion for cultivating both creative problem-solving skills and strong leadership qualities, Owen combines instructional expertise with practical design knowledge to create engaging learning experiences. Their courses equip students with the tools and confidence needed to excel in user-centered design and lead effectively in collaborative environments.', '2024-12-29', '2025-11-19 13:42:27', 'M.S. in Data Science', 'Duke University', 'CFA'),
(479, 'Reagan Johnston is an experienced instructor specializing in Leadership and Project Management courses, bringing a unique perspective shaped by a robust background in software engineering. With hands-on expertise in managing complex technical projects and leading high-performing teams, Reagan equips students with practical insights and industry-tested strategies for driving organizational success. Dedicated to fostering critical thinking and professional growth, Reagan creates dynamic learning environments where aspiring leaders can develop the skills needed to excel in today''s competitive business landscape.', '2025-01-18', '2025-03-01 11:03:26', 'M.S. in Engineering Management', 'Harvard Business School', 'Lean Six Sigma Green Belt'),
(500, 'Silas Gutierrez is an experienced instructor specializing in Data Analysis and Communication courses, bringing valuable real-world insight from a background as an HR Manager. With expertise in translating complex data insights into clear, actionable communication, Silas empowers students to develop critical analytical skills while mastering the art of presenting findings to diverse audiences. Passionate about bridging the gap between technical proficiency and professional communication, Silas creates engaging learning experiences that prepare students for success in today''s data-driven workplace.', '2025-02-05', '2026-01-14 13:12:46', 'M.S. in Human-Computer Interaction', 'University of Pennsylvania', 'SHRM-SCP');


