INSERT INTO `organizations` (`org_id`, `name`, `website`, `email`, `phone`, `description`, `type`, `created_at`) VALUES

(1, 'Stanford Professional Education', 'https://online.stanford.edu', 'org0001@example.invalid', NULL, 'Stanford University''s professional development arm offering executive education and certificate programs in technology and leadership.', 'University', '2024-02-13 07:23:19'),
(2, 'MIT Sloan Executive Education', 'https://executive.mit.edu', 'org0002@example.invalid', NULL, 'Massachusetts Institute of Technology''s business school providing cutting-edge management and technical training for professionals.', 'University', '2024-02-28 23:06:34'),
(3, 'Wharton Online', 'https://online.wharton.upenn.edu', 'org0003@example.invalid', NULL, 'University of Pennsylvania''s Wharton School delivering world-class business education through digital learning experiences.', 'University', '2023-12-25 03:45:27'),
(4, 'Accenture Academy', 'https://academy.accenture.com', 'org0004@example.invalid', NULL, 'Accenture''s learning platform focused on digital transformation, consulting methodologies, and enterprise technology skills.', 'Corporate Training', '2023-01-14 00:08:52'),
(5, 'Google Career Certificates', 'https://grow.google/certificates', 'org0005@example.invalid', NULL, 'Google''s professional certificate programs designed to prepare learners for high-growth careers in technology fields.', 'Corporate Training', '2024-02-17 08:01:51'),
(6, 'Microsoft Learn', 'https://learn.microsoft.com', 'org0006@example.invalid', NULL, 'Microsoft''s official learning platform offering technical training, certifications, and professional development resources.', 'Corporate Training', '2024-03-27 19:56:35'),
(7, 'General Assembly', 'https://generalassemb.ly', 'org0007@example.invalid', NULL, 'Pioneer in tech bootcamps offering immersive programs in software engineering, data science, UX design, and product management.', 'Bootcamp', '2023-03-04 15:18:38'),
(8, 'Springboard', 'https://www.springboard.com', 'org0008@example.invalid', NULL, 'Online bootcamp with mentor-led programs in data science, UX design, and software engineering with job guarantees.', 'Bootcamp', '2024-09-08 19:24:50'),
(9, 'PMI Learning', 'https://www.pmi.org/learning', 'org0009@example.invalid', NULL, 'Project Management Institute''s educational division offering PMP certification prep and project management courses.', 'Professional Association', '2024-01-14 11:58:41'),
(10, 'SHRM Education', 'https://www.shrm.org/learning', 'org0010@example.invalid', NULL, 'Society for Human Resource Management''s learning center for HR professionals seeking certification and skill development.', 'Professional Association', '2023-10-03 15:58:53'),
(11, 'Pluralsight', 'https://www.pluralsight.com', 'org0011@example.invalid', NULL, 'Technology workforce development platform with expert-authored courses in software development, IT, and creative skills.', 'EdTech Company', '2024-10-27 19:23:17'),
