-- fabricate-flush
INSERT INTO certificates (enrollment_id, certificate_number, completed_at, issued_at)
SELECT
  e.enrollment_id,
  CONCAT('CERT-', LPAD(e.enrollment_id, 8, '0')) AS certificate_number,
  COALESCE(e.last_accessed_at, e.enrolled_at) AS completed_at,
  NOW() AS issued_at
FROM enrollments e
LEFT JOIN certificates c
  ON c.enrollment_id = e.enrollment_id
WHERE e.status = 'completed'
  AND c.enrollment_id IS NULL;


SET FOREIGN_KEY_CHECKS = 1;
